/* ============ HELPERS ============ */
/* phase23: sound (Luke at the stern, the soundings, 27:27-29); bow (Paul and the skiff, 27:30-32); hold (the meal, 27:33-38, then the bay
   and the wreck, 27:39-43); planks (the foredeck of the wreck); surf (the crossing); count (Luke on the beach, 27:44); talk (the talk in
   pictures, 28:1, 2); fire (by the fire, the viper, 28:3-6); estate (the estate of Publius, 28:7-10) */
const phase23=()=>!F.anchors?'sound':!F.ropes?'bow':!F.bread?'hold':!F.planks?'planks':!F.surf?'surf':!F.found?'count':!F.malta?'talk':!F.viper?'fire':'estate';
const lukePlays=()=>{const p=phase23();return p==='sound'||p==='count'||p==='talk'||p==='fire'||p==='estate'};
const wet23=()=>{const p=phase23();return p==='planks'||p==='surf'||p==='count'||p==='talk'||p==='fire'};
/* the room Luke's tablet goes back to */
const lukeRoom23=()=>{const p=phase23();return p==='sound'?'stern23':p==='estate'?'estate23':'beach23'};
function setPC23(a){if(G.pc!==a){G.pc=a;G.inv=G.invs[a.id]||(G.invs[a.id]=[])}}
function show23(room,x,y,dir){place23(room);dealInv(room);const e=ENT[room];enterRoom(room,x!=null?x:e[0],y!=null?y:e[1],dir||e[2]);drawInv();codeBtn()}
async function goto23(room,x,y,dir){await fade(1,300);show23(room,x,y,dir);await fade(0,300)}
const tw=ms=>wait(fast()?Math.min(40,ms):ms);
async function go23(a,x,y,sp){a.speed=fast()?400:sp||0;a.free=1;await walk(a,x,y);a.speed=0;a.free=0}
const TL={thought:1,color:'#d0e8e0'};   /* Luke's thoughts */
const TP={thought:1,color:'#cfe2ff'};   /* Paul's */
const TH=()=>PC()===LK?TL:TP;
/* the count on the beach: the groups counted, and the old prisoner once found */
const count23=()=>GROUPS23.reduce((s,g)=>s+(F[g.k]?g.n:0),0)+(F.found?1:0);
/* the planks: who stands at which float (G.pk23; not in the code: only the finished pairing is) */
const pk23=()=>G.pk23||(G.pk23={sel:null,on:{}});
const lookOf23=k=>{const a=PEOPLE23.find(p=>p.k===k).a();return a===SO1?(F.mailOff?'soldier23au':'soldier23aw'):a.id+'w'};
function at23(k){const S=pk23(),f=FLOATS23.find(f=>f.k===S.on[k]);if(f){const i=Object.keys(S.on).filter(q=>S.on[q]===f.k).indexOf(k);return f.at[Math.min(i,f.at.length-1)]}
  return[PEOPLE23.find(p=>p.k===k).x,PEOPLE_Y23]}

