/* ---- the talk in pictures (28:1, 2): Luke ---- */
async function talk23(){if(F.malta)return say(LK,'luke_one_word_and_no_more',TL);
  for(;;){const ex=G.ex23||0,X=TALK23[ex];EL.ges=1;await say(LK,X.ask,TL);EL.ges=0;
    const i=await choose(PICS23.concat(['wait_a_moment']),{keep:1});if(i===PICS23.length)return;const k=PICS23[i].key;
    if(k!==X.right){EL.ges=2;await say(LK,X.no[k],TL);EL.ges=0;continue}
    if(X.ok){await say(LK,X.ok,TL);G.ex23=ex+1;continue}
    /* Luke's own question: the ground he stands on; the islander says the island's name */
    await say(EL,'malta_the_name',{to:LK});await say(LK,'malta_luke_says_it_after_him',{to:EL});G.ex23=0;return named23()}}
