/* ---- by the fire: the viper (28:3-6), a cutscene that is not played; Luke watches ---- */
async function viper23scene(){if(phase23()!=='fire')return;
  /* Paul brings a bundle of sticks and lays it on the fire */
  P.pose='bundle';place(P,'beach23',40,124,1);await go23(P,FIRE23[0]-14,FIRE23[1]+4,40);P.pose=0;P.dir=1;
  G.vip23={fr:0,x:FIRE23[0]-2,y:FIRE23[1]+1,dir:-1};await tw(400);
  /* 28:3: the heat drives it out; it fastens on his hand */
  const told3=tell('m3');G.vip23.fr=1;await tw(700);G.vip23.fr=2;G.vip23.x-=4;await tw(600);P.pose='shake';P.pk=0;G.vip23.fr=3;
  const sway=setInterval(()=>{if(G.vip23&&(G.vip23.fr===3||G.vip23.fr===4))G.vip23.fr=G.vip23.fr===3?4:3},fast()?60:420);await wait(fast()?200:600);await told3;
  /* 28:4: what the islanders say to one another; Paul does not understand it and does not react */
  IS1.dir=1;IS5.dir=-1;await tell('m4');clearInterval(sway);
  /* 28:5: he shakes it off into the fire */
  P.pk=1;const h=poseAt(P.look,'shake1');G.vip23={fr:5,x:P.x+(h?h.far[0]:10)*P.dir,y:P.y+(h?h.far[1]:-24),dir:P.dir};await tw(300);
  G.vip23.fr=6;await tween(fast()?60:500,k=>{G.vip23.x+=(FIRE23[0]-G.vip23.x)*k*.4;G.vip23.y+=(FIRE23[1]-2-G.vip23.y)*k*.4});G.vip23=null;
  P.pose='warm';P.pk=0;await tell('m5');
  /* 28:6: the long wait, the light going over; then they call him a god, and nothing is shown */
  await Promise.all([tween(fast()?100:5200,k=>{G.lw23=k}),tell('m6')]);
  F.viper=1;await fade(1,800);G.lw23=0;P.pose=0;show23('estate23');await fade(0,700);await tell('m7');codeBtn()}
/* ---- the estate of Publius (28:7-10): Luke ---- */
